        "title": "강 건너기 문제를 BFS로 풀기",
        "body": [
         "<p>상태는 '서쪽 둑에 남은 것들'로 나타내요(<code>fcsw|</code>가 초기 상태, <code>|fcsw</code>가 목표 상태). <code>safe</code> 함수가 금지 상태(양과 늑대만, 양과 양배추만 남음)를 걸러 내요.</p>"
        ],
        "code": {
         "lang": "python",
         "src": "# '강 건너기' 문제: 농부(f)·늑대(w)·양(s)·양배추(c)를 모두 건너편으로!\n# 상태 = 서쪽 둑에 남아 있는 것들의 집합. 처음은 {f,w,s,c}, 목표는 빈 집합.\nALL = frozenset(\"fwsc\")\n\ndef safe(bank):\n    # 농부가 없는 둑에 양+늑대 또는 양+양배추가 함께 있으면 금지 상태\n    if \"f\" in bank:\n        return True\n    return not ({\"s\", \"w\"} <= bank or {\"s\", \"c\"} <= bank)\n\ndef moves(west):\n    farmer_west = \"f\" in west\n    here = west if farmer_west else ALL - west     # 농부가 있는 쪽\n    result = []\n    for cargo in [None] + sorted(here - {\"f\"}):    # 혼자 또는 하나만 태우기\n        moving = {\"f\"} | ({cargo} if cargo else set())\n        new_west = west - moving if farmer_west else west | moving\n        new_west = frozenset(new_west)\n        if safe(new_west) and safe(ALL - new_west):\n            result.append(new_west)\n    return result\n\ndef show(west):\n    order = \"fcsw\"                                  # 교과서처럼 f, c, s, w 순서로 쓰기\n    left = \"\".join(x for x in order if x in west)\n    right = \"\".join(x for x in order if x not in west)\n    return left + \"|\" + right\n\ndef bfs_path(start, goal):\n    queue, parent = deque([start]), {start: None}\n    while queue:\n        s = queue.popleft()\n        if s == goal:\n            path = []\n            while s is not None:\n                path.append(s); s = parent[s]\n            return path[::-1], len(parent)\n        for n in moves(s):\n            if n not in parent:\n                parent[n] = s\n                queue.append(n)\n\npath, seen = bfs_path(ALL, frozenset())\nprint(\"BFS로 찾은 해 (강 건너기 횟수:\", len(path) - 1, \")\")\nprint(\"  \" + \"  →  \".join(show(s) for s in path))\nprint(\"만들어 본 상태 수:\", seen)",
         "run": true
        },
