         "src": "# 8개의 숫자 조각 퍼즐 (교과서 [그림 I-14])\n# 0은 빈칸이에요. 3x3 판을 한 줄(길이 9 튜플)로 펼쳐서 저장해요.\nstart = (1, 2, 3,\n         7, 4, 5,\n         0, 8, 6)\ngoal  = (1, 2, 3,\n         4, 5, 6,\n         7, 8, 0)\n\ndef show(state):\n    for r in range(3):\n        print(\"  \" + \" \".join(str(x) if x else \"_\" for x in state[r*3:r*3+3]))\n\ndef score(state):\n    # 평가 함수: 목표 상태와 같은 위치에 놓인 조각의 수 (빈칸은 세지 않아요)\n    return sum(1 for i in range(9) if state[i] != 0 and state[i] == goal[i])\n\nprint(\"초기 상태\"); show(start)\nprint(\"평가 함숫값 f =\", score(start))",
