         "src": "# 언덕 등반 탐색이 '막히는' 경우도 있을까요?\nstuck = (1, 2, 3,\n         4, 8, 5,\n         7, 6, 0)\nprint(\"새 출발 상태 (f =\", score(stuck), \")\"); show(stuck)\nfinal, ok = hill_climb(stuck)\nprint(\"결과:\", \"목표 도달\" if ok else \"목표가 아닌 곳에서 멈춤\")\n\n# 정말 풀 수 없는 상태일까? 너비 우선 탐색(맹목적 탐색)으로 확인해 봐요.\nfrom collections import deque\ndef bfs_moves(state):\n    parent = {state: None}\n    queue = deque([state])\n    while queue:\n        s = queue.popleft()\n        if s == goal:\n            n = 0\n            while parent[s] is not None:\n                s = parent[s]; n += 1\n            return n, len(parent)\n        for _, n in next_states(s):\n            if n not in parent:\n                parent[n] = s\n                queue.append(n)\n\nn, made = bfs_moves(stuck)\nprint(f\"BFS: {n}번 밀면 풀려요! (그 대신 상태를 {made}개나 만들어 봤어요)\")",
