         "src": "# 격자 미로에서 A*와 깊이 우선 탐색(DFS)을 비교해 봐요.\n# S=출발, G=도착, #=벽, .=길\nmaze = [\n    \"S.........\",\n    \"...####...\",\n    \"......#...\",\n    \"..G...#...\",\n    \"......#...\",\n    \"..........\",\n]\nR, C = len(maze), len(maze[0])\nfind = lambda ch: next((r, c) for r in range(R) for c in range(C) if maze[r][c] == ch)\nS, G = find(\"S\"), find(\"G\")\n\ndef neighbors(p):\n    r, c = p\n    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:    # 오른쪽, 아래, 왼쪽, 위 순서\n        nr, nc = r + dr, c + dc\n        if 0 <= nr < R and 0 <= nc < C and maze[nr][nc] != \"#\":\n            yield (nr, nc)\n\ndef dfs_grid():\n    stack, parent, order = [S], {S: None}, []\n    while stack:\n        p = stack.pop()\n        order.append(p)\n        if p == G: break\n        for n in reversed(list(neighbors(p))):\n            if n not in parent:\n                parent[n] = p; stack.append(n)\n    return parent, order\n\ndef astar_grid():\n    hh = lambda p: abs(p[0] - G[0]) + abs(p[1] - G[1])   # 남은 가로+세로 칸 수\n    g, parent, open_list, closed, order = {S: 0}, {S: None}, [S], set(), []\n    while open_list:\n        p = min(open_list, key=lambda q: (g[q] + hh(q), hh(q)))\n        open_list.remove(p); closed.add(p); order.append(p)\n        if p == G: break\n        for n in neighbors(p):\n            if n not in closed and (n not in g or g[p] + 1 < g[n]):\n                g[n] = g[p] + 1; parent[n] = p\n                if n not in open_list: open_list.append(n)\n    return parent, order\n\ndef draw(parent):\n    path, p = set(), G\n    while p: path.add(p); p = parent[p]\n    for r in range(R):\n        print(\"  \" + \"\".join(\"*\" if (r, c) in path and maze[r][c] == \".\" else maze[r][c] for c in range(C)))\n    return len(path) - 1\n\nfor name, fn in [(\"DFS\", dfs_grid), (\"A*\", astar_grid)]:\n    parent, order = fn()\n    print(f\"[{name}]\")\n    steps = draw(parent)\n    print(f\"  경로 길이 {steps}칸, 꺼내서 살펴본 칸 {len(order)}개\")",
