         "src": "# 틱택토에 미니맥스 적용하기: 지금 판에서 O(MAX)가 둘 최선의 수는?\n# 칸 번호      판 상태 (O 차례)\n# 0 1 2        O X O\n# 3 4 5        . X .\n# 6 7 8        . . .\nboard = list(\"OXO.X....\")\nLINES = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]\ndef winner(b):\n    for a, c, d in LINES:\n        if b[a] != \".\" and b[a] == b[c] == b[d]:\n            return b[a]\n    return None\n\ncount = 0\ndef minimax(b, turn):\n    global count\n    count += 1\n    w = winner(b)\n    if w == \"O\": return 1          # O 승리\n    if w == \"X\": return -1         # X 승리\n    if \".\" not in b: return 0      # 무승부\n    scores = []\n    for i in range(9):\n        if b[i] == \".\":\n            b[i] = turn\n            scores.append(minimax(b, \"X\" if turn == \"O\" else \"O\"))\n            b[i] = \".\"\n    return max(scores) if turn == \"O\" else min(scores)   # O는 MAX, X는 MIN\n\nfor i in range(9):\n    if board[i] == \".\":\n        board[i] = \"O\"\n        print(f\"O를 {i}번 칸에 두면 → 값 {minimax(board, 'X')}\")\n        board[i] = \".\"\nprint(\"살펴본 판의 수:\", count)",
